const TI_PRE_WEEK_TOPICS = new Map(TI_REVIEW_CARDS.map(card=>[card.id,card.topic]));
// Subtopics belong to exactly one weekly block; the week prefix prevents collisions.
function tiLectureSubtopic(id,week){
  if(week.id==="ti_vl_01_02"){
    if(/^doc_ti_extra_00[3-9]$/.test(id)||id==="doc_ti_extra_010"||id==="doc_ti_vl_20261022_004")return "Reguläre Ausdrücke und reguläre Sprachen";
    if(["doc_ti_intro_063","doc_ti_intro_064","doc_ti_intro_065","doc_ti_intro_066","doc_ti_intro_067","doc_ti_extra_001","doc_ti_extra_002","doc_ti_vl_20261022_001","doc_ti_vl_20261022_002","doc_ti_vl_20261022_003"].includes(id))return "Operationen auf Sprachen";
    return "Alphabete, Wörter und formale Sprachen";
  }
  if(week.id==="ti_vl_03_04"){
    const n=Number(id.slice(-3));
    if(n===14)return "Äquivalenz von Automaten";
    if(n===24)return "Satz von Kleene: Aussage";
    if(n>=22)return "Abschlusseigenschaften regulärer Sprachen";
    if(n>=16)return "Potenzmengenkonstruktion";
    if([7,8,9,10,12,13].includes(n))return "Konfigurationen und Akzeptanz";
    return "DEA, NEA und Übergänge";
  }
  if(week.id==="ti_vl_05_06"){
    if(id.startsWith("doc_ti_countability_")||id==="doc_ti_vl_20261022_027")return "Mächtigkeiten und Abzählbarkeit";
    if(id==="doc_ti_pumping_example_001")return "Pumping-Lemma";
    const n=Number(id.slice(-3));
    if(n<=33)return "Pumping-Lemma";
    if(n<=35)return "Beweismethoden und Induktion";
    if(n<=38)return "Satz von Kleene: Beweis und Rekursion";
    return "Äquivalenzrelationen und Rechtskongruenz";
  }
  if(week.id==="ti_vl_07_08"){
    if(id==="doc_ti_nerode_003")return "Satz von Myhill-Nerode";
    if(id==="doc_ti_nerode_004")return "Äquivalenz von Zuständen";
    if(id==="doc_ti_vl_20261022_043")return "Unterscheidbare Wörter und Zustände";
    if(id==="doc_ti_emptiness_001")return "Leerheitsproblem für DEA";
    return "Äquivalenzklassen bezüglich Sprache und DEA";
  }
  return TI_PRE_WEEK_TOPICS.get(id)||"Weitere Inhalte";
}
const TI_WEEKLY_CARD_WEEKS = new Map(TI_LECTURE_WEEKS.flatMap(week=>week.cardIds.map(id=>[id,week.topic])));
const TI_WEEKLY_CARD_TOPICS = new Map(TI_LECTURE_WEEKS.flatMap(week=>week.cardIds.map(id=>[id,week.topic.split(" | ")[0]+": "+tiLectureSubtopic(id,week)])));
const TI_TOPIC_BLOCKS = TI_LECTURE_WEEKS.map(week=>({id:week.id,subject:"Theoretische Informatik",name:week.topic,topics:[...new Set(week.cardIds.map(id=>TI_WEEKLY_CARD_TOPICS.get(id)))]}));
TI_REVIEW_CARDS.forEach(card=>{if(TI_WEEKLY_CARD_TOPICS.has(card.id))card.topic=TI_WEEKLY_CARD_TOPICS.get(card.id)});
